const raw = $json.choices?.[0]?.message?.content || '{}';
let r;
try { r = JSON.parse(raw); } catch (e) { r = { error: 'KI-Antwort war kein JSON' }; }
// Panel erwartet `summary`
if (r.summary_de !== undefined) { r.summary = r.summary_de; delete r.summary_de; }
// Gedankenstriche sicherheitshalber entfernen
if (r.draft) r.draft = r.draft.replace(/\s[–—]\s/g, ', ').replace(/[–—]/g, '-');
return [{ json: { threadId: $('Verlauf laden').first().json.threadId, result: r } }];
